import json
import sys

def deep_merge(a, b):
    if isinstance(a, dict) and isinstance(b, dict):
        res = a.copy()
        for key, value in b.items():
            if key in res:
                res[key] = deep_merge(res[key], value)
            else:
                res[key] = value
        return res
    elif isinstance(a, list) and isinstance(b, list):
        res = list(a)
        for item in b:
            if item not in res:
                res.append(item)
        return res
    else:
        return b

