        let name: String
        let department: String
        let salary: Double
    }

    var employees: [Employee] = []
    for i in 1..<lines.count {
        let columns = lines[i].split(separator: ",").map { $0.trimmingCharacters(in: .whitespaces) }
        if columns.count >= 4 {
            let name = String(columns[1])
            let dept = String(columns[2])
            if let salary = Double(columns[3]) {
                employees.append(Employee(name: name, department: dept, salary: salary))
            }
        }
    }

    var deptSalaries: [String: [Double]] = [:]
    var deptCounts: [String: Int] = [:]
    var totalBudget: Double = 0
    var highestPaid: Employee?

    for emp in employees {
        deptSalaries[emp.department, default: []].append(emp.salary)
        deptCounts[emp.department, default: 0] += 1
        totalBudget += emp.salary
        if highestPaid == nil || emp.salary > highestPaid!.salary {
            highestPaid = emp
        }
    }

    let avgFormatter = NumberFormatter()
    avgFormatter.minimumFractionDigits = 2
    avgFormatter.maximumFractionDigits = 2
    avgFormatter.numberStyle = .decimal

