import * as fs from 'fs';

const filePath = '/tmp/…/employees.csv';

function solve() {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.trim().split(/\r?\n/);

    if (lines.length <= 1) return;

    const employees: { name: string; department: string; salary: number }[] = [];

    for (let i = 1; i < lines.length; i++) {
      const line = lines[i].trim();
      if (!line) continue;

      const cols = line.split(',');
      if (cols.length < 4) continue;

      const name = cols[1].trim();
      const dept = cols[2].trim();
      const salary = parseFloat(cols[3].trim());

      employees.push({ name, department: dept, salary });
    }

    const deptSums: Record<string, number> = {};
    const deptCounts: Record<string, number> = {};
    let highestPaid = { name: '', salary: -Infinity };
    let totalBudget = 0;

    for (const emp of employees) {
      totalBudget += emp.salary;
      deptSums[emp.department] = (deptSums[emp.department] || 0) + emp.salary;
      deptCounts[emp.department] = (deptCounts[emp.department] || 0) + 1;

      if (emp.salary > highestPaid.salary) {
        highestPaid = { name: emp.name, salary: emp.salary };
      }
    }

    const sortedDepts = Object.keys(deptSums).sort();

    console.log('=== Salary Report ===');
    console.log('');
    console.log('Average Salary by Department:');
    for (const dept of sortedDepts) {
      const avg = deptSums[dept] / deptCounts[dept];
      console.log(`  ${dept}: $${avg.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`);
    }

    console.log('');
    console.log(`Highest Paid: ${highestPaid.name} ($${Math.round(highestPaid.salary).toLocaleString('en-US')})`);

    console.log('');
    console.log('Departments with >2 employees:');
    for (const dept of sortedDepts) {
      if (deptCounts[dept] > 2) {
        console.log(`  ${dept} (${deptCounts[dept]} employees)`);
      }
    }

    console.log('');
    console.log(`Total Budget: $${Math.round(totalBudget).toLocaleString('en-US')}`);
  } catch (error) {
    // Silent error handling as per requirements to write only specified output
  }
}

