import * as fs from 'fs';

/**
 * Helper to check if a value is a plain object (not an array or null).
 */
function isObject(val: any): boolean {
  return val !== null && typeof val === 'object' && !Array.isArray(val);
}

/**
 * Generates a canonical string representation of a value to ensure 
 * deep equality-based duplicate removal in arrays, regardless of key order.
 */
function getCanonical(val: any): string {
  if (val === null) return 'null';
  if (typeof val === 'undefined') return 'undefined';
  if (Array.isArray(val)) {
    return '[' + val.map(getCanonical).join(',') + ']';
  } else if (isObject(val)) {
    const keys = Object.keys(val).sort();
    return '{' + keys.map(k => `"${k}":${getCanonical(val[k])}`).join(',') + '}';
  } else {
    return JSON.stringify(val);
  }
}

/**
 * Performs the deep merge based on the specified rules.
 */
function deepMerge(a: any, b: any): any {
  if (isObject(a) && isObject(b)) {
    const result: any = {};
    // Get all unique keys from both objects and sort them for deterministic output
    const allKeys = Array.from(new Set([...Object.keys(a), ...Object.keys(b)])).sort();

    for (const key of allKeys) {
      if (key in a && key in b) {
        result[key] = deepMerge(a[key], b[key]);
      } else if (key in a) {
        result[key] = a[key];
      } else {
        result[key] = b[key];
      }
    }
    return result;
  } else if (Array.isArray(a) && Array.isArray(b)) {
    const combined = [...a, ...b];
    const result: any[] = [];
    const seen = new Set<string>();

    for (const item of combined) {
      const s = getCanonical(item);
      if (!seen.has(s)) {
        seen.add(s);
        result.push(item);
      }
    }
    return result;
  } else {
    // Scalar conflict or type mismatch: B overrides A
    return b;
  }
}

