async function run(): Promise<void> {
  const url = 'http://127.0.0.1:18923/api/products';

  try {
    const products: Product[] = await new Promise((resolve, reject) => {
      http.get(url, (res) => {
        let body = '';
        res.on('data', (chunk) => {
          body += chunk;
        });
        res.on('end', () => {
          try {
            resolve(JSON.parse(body));
          } catch (e) {
            reject(e);
          }
        });
      }).on('error', (err) => {
        reject(err);
      });
    });

    const filtered = products.filter((p) => p.price > 50.00);
    filtered.sort((a, b) => a.name.localeCompare(b.name));

    console.log('=== Filtered Products (price > $50.00) ===');
