    let total = 0;
    for (const p of filtered) {
      console.log(`${p.name}: $${p.price.toFixed(2)}`);
      total += p.price;
    }

    console.log('');
    console.log(`Count: ${filtered.length}`);
    console.log(`Total: $${total.toFixed(2)}`);
  } catch (error) {
    // Error handling for runtime execution
  }
}

