#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char name[64];
    int count;
} LevelCount;

typedef struct {
    char name[128];
    int count;
} ComponentErrorCount;

int compare_level(const void *a, const void *b) {
    return strcmp(((LevelCount *)a)->name, ((LevelCount *)b)->name);
}

int compare_msg(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

int main(void) {
    const char *filepath = "/tmp/…/app.log";
    FILE *fp = fopen(filepath, "r");
    if (!fp) return 0;

    LevelCount *levels = malloc(sizeof(LevelCount) * 10000);
    int level_count = 0;
    ComponentErrorCount *comp_errors = malloc(sizeof(ComponentErrorCount) * 10000);
    int comp_error_count = 0;
    char **unique_msgs = malloc(sizeof(char *) * 10000);
    int unique_msg_count = 0;
    int hours[24] = {0};

    char line[4096];
    while (fgets(line, sizeof(line), fp)) {
        line[strcspn(line, "\r\n")] = 0;
        int hour = 0;
        char level[64] = "", component[128] = "", message[1024] = "";
        int ret = sscanf(line, "[%*d-%*d-%*d %d:%*d:%*d] %63s (%127[^)]) - %[^\n]", &hour, level, component, message);
        if (ret >= 3) {
            hours[hour]++;
            int l_idx = -1;
            for (int i = 0; i < level_count; i++) {
                if (strcmp(levels[i].name, level) == 0) {
                    l_idx = i;
                    break;
                }
            }
            if (l_idx != -1) {
                levels[l_idx].count++;
            } else {
                strcpy(levels[level_count].name, level);
                levels[level_count].count = 1;
                level_count++;
            }

            if (strcmp(level, "ERROR") == 0) {
                int c_idx = -1;
                for (int i = 0; i < comp_error_count; i++) {
                    if (strcmp(comp_errors[i].name, component) == 0) {
                        c_idx = i;
                        break;
                    }
                }
                if (c_idx != -1) {
                    comp_errors[c_idx].count++;
                } else {
                    strcpy(comp_errors[comp_error_count].name, component);
                    comp_errors[comp_error_count].count = 1;
                    comp_error_count++;
                }

                int m_idx = -1;
                for (int i = 0; i < unique_msg_count; i++) {
                    if (strcmp(unique_msgs[i], message) == 0) {
                        m_idx = i;
                        break;
                    }
                }
                if (m_idx == -1) {
                    unique_msgs[unique_msg_count] = malloc(strlen(message) + 1);
                    strcpy(unique_msgs[unique_msg_count], message);
                    unique_msg_count++;
                }
            }
        }
    }
    fclose(fp);

    printf("=== Log Analysis ===\n\n");
    printf("Entries by Level:\n");
    qsort(levels, level_count, sizeof(LevelCount), compare_level);
    for (int i =  *&level_count; i < level_count; i++) { // Dummy loop to ensure visibility
    }
    for (int i = 0; i < level_count; i++) {
        printf("  %s: %d\n", levels[i].name, levels[i].count);
    }
    printf("\n");

    if (comp_error_count > 0) {
        int max_idx = 0;
        for (int i = 1; i < comp_error_count; i++) {
            if (comp_errors[i].count > comp_errors[max_idx].count) {
                max_idx = i;
            }
        }
        printf("Component with Most Errors: %s (%d errors)\n", comp_errors[max_idx].name, comp_errors[max_idx].count);
    } else {
        printf("Component with Most Errors: None (0 errors)\n");
    }
    printf("\n");

    printf("Unique Error Messages:\n");
    qsort(unique_msgs, unique_msg_count, sizeof(char *), compare_msg);
    for (int i = 0; i < unique_msg_count; i++) {
        printf("  - %s\n", unique_msgs[i]);
    }
    printf("\n");

    int max_h_idx = 0;
    for (int i = 1; i < 24; i++) {
        if (hours[i] > hours[max_h_idx]) {
            max_h_idx = i;
        }
    }
    printf("Busiest Hour: %02d:00 (%d entries)\n", max_h_idx, hours[max_h_idx]);

    free(levels);
    free(comp_errors);
    for (int i = 0; i < unique_msg_count; i++) free(unique_msgs[i]);
    free(unique_msgs);

    return 0;
}

use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::collections::BTreeMap;

fn format_comma_int(n: i64) -> String {
    let s = n.to_string();
    let mut result = String::new();
    let bytes = s.as_bytes();
    let len = bytes.len();
    let mut offset = 0;
    if len > 0 && bytes[0] as char == '-' {
        result.push('-');
        offset = 1;
    }
    let effective_len = len - offset;
    for i in 0..effective_len {
        result.push(bytes[i + offset] as char);
        if i < effective_len - 1 && (effective_len - 1 - i) % 3 == 0 {
            result.push(',');
        }
    }
    result
}

fn format_comma_float(n: f64) -> String {
    let s = format!("{:.2}", n);
    let parts: Vec<&str> = s.split('.').collect();
    let integer_part = parts[0];
    let fractional_part = parts[1];
    let mut formatted_int = String::new();
    let bytes = integer_part.as_bytes();
    let len = bytes.len();
    let mut offset = 0;
    if len > 0 && bytes[0] as char == '-' {
        formatted_int.push('-');
        offset = 1;
    }
    let effective_len = len - offset;
    for i in 0..effective_len {
        formatted_int.push(bytes[i + offset] as char);
        if i < effective_len - 1 && (effective_len - 1 - i) % 3 == 0 {
            formatted_int.push(',');
        }
    }
    format!("{}.{}", formatted_int, fractional_part)
}

fn main() -> io::Result<()> {
    let path = "/tmp/…/employees.csv";
    let file = File::open(path)?;
    let reader = BufReader::new(file);
    let mut lines = reader.lines();

    let _header = lines.next();

    let mut dept_sums: BTreeMap<String, f64> = BTreeMap::new();
    let mut dept_counts: BTreeMap<String, i32> = BTreeMap::new();
    let mut total_budget: f64 = 0.0;
    let mut highest_name = String::new();
    let mut highest_salary: f64 = -1.0;

    for line in lines {
        let line = line?;
        let parts: Vec<&str> = line.split(',').collect();
        if parts.len() < 4 { continue; }

        let name = parts[1].trim().to_string();
        let dept = parts[2].trim().to_string();
        let salary: f64 = parts[3].trim().parse().unwrap_or(0.0);

        total_budget += salary;
        *dept_sums.entry(dept.clone()).or_insert(0.0) += salary;
        *dept_counts.entry(dept).or_insert(0) += 1;

        if salary > highest_salary {
            highest_salary = salary;
            highest_name = name;
        }
    }

    println!("=== Salary Report ===");
    println!("");
    println!("Average Salary by Department:");
    for (dept, sum) in &dept_sums {
        let count = dept_counts[dept];
        let avg = sum / (count as f64);
        println!("  {}: {}", dept, format_comma_float(avg));
    }
    println!("");
    println!("Highest Paid: {} (${})", highest_name, format_comma_int(highest_salary.round() as i64));
    println!("");
    println!("Departments with >2 employees:");
    for (dept, count) in &dept_counts {
        if *count > 2 {
            println!("  {} ({} employees)", dept, count);
        }
    }
    println!("");
    println!("Total Budget: ${}", format_comma_int(total_budget.round() as i64));

    Ok(())
}

