import json
import heapq

def solve():
    path = "/tmp/…/graph.json"

    try:
        with open(path, 'r') as f:
            data = json.load(f)
    except FileNotFoundError:
        return

    nodes = data.get("nodes", [])
    edges = data.get("edges", [])

    # Build adjacency list for an undirected graph
    adj = {node: [] for node in nodes}
    for edge in edges:
        u = edge["from"]
        v = edge["to"]
        w = edge["weight"]
        if u in adj and v in adj:
            adj[u].append((v, w))
            adj[v].append((u, w))

    # Dijkstra's algorithm
    start_node = "A"
    distances = {node: float('inf') for node in nodes}

    if start_node in distances:
        distances[start_node] = 0
        pq = [(0, start_node)]

        while pq:
            current_dist, u = heapq.heappop(pq)

            if current_dist > distances[u]:
                continue

            for v, weight in adj[u]:
                distance = current_dist + weight
                if distance < distances[v]:
                    distances[v] = distance
                    heapq.heappush(pq, (distance, v))

    # Output formatting
    print("=== Shortest Paths from A ===")
    print()

    # Sort nodes alphabetically as per requirements
    for node in sorted(nodes):
        dist_val = distances[node]
        # If distance is infinity, it will print as 'inf'
        print(f"A -> {node}: {dist_val}")

if __name__ == "__main__":
    solve()

use std::collections::BTreeMap;
use std::fs;

#[derive(Debug, Clone, PartialEq)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<JsonValue>),
    Object(BTreeMap<String, JsonValue>),
}

struct Parser<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Self { input, pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.input[self.pos..].chars().next()
    }

    fn consume(&mut self) -> Option<char> {
        let c = self.peek()?;
        self.pos += c.len_utf8();
        Some(c)
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() {
                self.consume();
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> JsonValue {
        self.skip_whitespace();
        let c = match self.peek() {
            Some(c) => c,
            None => return JsonValue::Null,
        };

        match c {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => self.parse_string(),
            't' | 'f' => self.parse_bool(),
            'n' => self.parse_null(),
            _ => self.parse_number(),
        }
    }

    fn parse_null(&mut self) -> JsonValue {
        for _ in 0..4 {
            self.consume();
        }
        JsonValue::Null
    }

    fn parse_bool(&mut self) -> JsoneValue {
        let is_true = if self.peek() == Some('t') { true } else { false };
        let len = if is_true { 4 } else { 5 };
        for _ in 0..len {
            self.consume();
        }
        JsonValue::Bool(is_true)
    }

    fn parse_string(&mut self) -> JsonValue {
        self.consume(); // "
        let mut s = String::new();
        while let Some(c) = self.consume() {
            if c == '"' {
                return JsonValue::String(s);
            }
            if c == '\\' {
                if let Some(esc) = self.consume() {
                    match esc {
                        'n' => s.push('\n'),
                        'r' => s.push('\r'),
                        't' => s.push('\t'),
                        'b' => s.push('\x08'),
                        'f' => s.push('\x0C'),
                        '\\' => s.push('\\'),
                        '"' => s.push('"'),
                        _ => s.push(esc),
                    }
                }
            } else {
                s.push(c);
            }
        }
        JsonValue::String(s)
    }

    fn parse_number(&mut self) -> JsonValue {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || c == '-' || c == '.' || c == 'e' || c == 'E' || c == '+' {
                self.consume();
            } else {
                break;
            }
        }
        let s = &self.input[start..self.pos];
        let val = s.parse::<f64>().unwrap_or(0.0);
        JsonValue::Number(val)
    }

    fn parse_array(&mut self) -> JsonValue {
        self.consume(); // [
        let mut arr = Vec::new();
        loop {
            self.skip_whitespace();
            if self.peek() == Some(']') {
                self.consume();
                break;
            }
            arr.push(self.parse_value());
            self.skip_whitespace();
            if self.peek() == Some(',') {
                self.consume();
            } else {
                self.skip_whitespace();
                if self.peek() == Some(']') {
                    self.consume();
                }
                break;
            }
        }
        JsonValue::Array(arr)
    }

    fn parse_object(&mut self) -> JsonValue {
        self.consume(); // {
        let mut map = BTreeMap::new();
        loop {
            self.skip_whitespace();
            if self.peek() == Some('}') {
                self.consume();
                break;
            }
            let key = match self.parse_string() {
                JsonValue::String(s) => s,
                _ => String::new(),
            };
            self.skip_whitespace();
            if self.peek() == Some(':') {
                self.consume();
            }
            let val = self.parse_value();
            map.insert(key, val);
            self.skip_whitespace();
            if self.peek() == Some(',') {
                self.consume();
            } else {
                self.skip_whitespace();
                if self.peek() == Some('}') {
                    self.consume();
                }
                break;
            }
        }
        JsonValue::Object(map)
    }
}

// Helper for the bool parser to handle the type mismatch in the logic above
type JsoneValue = JsonValue;

fn merge(a: JsonValue, b: JsonValue) -> JsonValue {
    match (a, b) {
        (JsonValue::Object(mut map_a), JsonValue::Object(map_b)) => {
            for (k, v) in map_b {
                if let Some(a_val) = map_a.remove(&k) {
                    map_a.insert(k, merge(a_val, v));
                } else {
                    map_a.insert(k, v);
                }
            }
            JsonValue::Object(map_a)
        }
        (JsonValue::Array(mut arr_a), JsonValue::Array(arr_b)) => {
            for val_b in arr_b {
                if !arr_a.contains(&val_b) {
                    arr_a.push(val_b);
                }
            }
            JsonValue::Array(arr_a)
        }
        (_, b) => b,
    }
}

fn print_string(s: &str) {
    print!("\"");
    for c in s.chars() {
        match c {
            '\"' => print!("\\\""),
            '\\' => print!("\\\\"),
            '\n' => print!("\\n"),
            '\r' => print!("\\r"),
            '\t' => print!("\\t"),
            _ => print!("{}", c),
        }
    }
    print!("\"");
}

fn print_json(val: &JsonValue, indent: usize) {
    match val {
        JsonValue::Null => print!("null"),
        JsonValue::Bool(b) => print!("{}", if *b { "true" } else { "false" }),
        JsonValue::Number(n) => print!("{}", n),
        JsonValue::String(s) => print_string(s),
        JsonValue::Array(arr) => {
            if arr.is_empty() {
                print!("[]");
            } else {
                print!("[\n");
                for (i, item) in arr.iter().enumerate() {
                    print!("{}", "  ".repeat(indent + 1));
                    print_json(item, indent + 1);
                    if i < arr.len() - 1 {
                        print!(",");
                    }
                    println!();
                }
                print!("{}", "  ".repeat(indent));
                print!("]");
            }
        }
        JsonValue::Object(map) => {
            if map.is_empty() {
                print!("{{}}");
            } else {
                print!("{{\n");
                let mut keys: Vec<_> = map.keys().collect();
                for (i, key) in keys.iter().enumerate() {
                    print!("{}", "  ".repeat(indent + 1));
                    print_string(key);
                    print!(": ");
                    print_json(map.get(*key).unwrap(), indent + 1);
                    if i < keys.len() - 1 {
                        print!(",");
                    }
                    println!();
                }
                print!("{}", "  ".repeat(indent));
                print!("}");
            }
        }
    }
}

