import java.util.*;
import java.nio.file.*;
import java.util.regex.*;

public class Main {
    static class Edge {
        String to;
        double weight;

        Edge(String to, double weight) {
            this.to = to;
            this.weight = weight;
        }
    }

    static class NodeDist implements Comparable<NodeDist> {
        String name;
        double dist;

        NodeDist(String name, double dist) {
            this.name = name;
            this.dist = dist;
        }

        @Override
        public int compareTo(NodeDist other) {
            return Double.compare(this.dist, other.dist);
        }
    }

    static String formatDistance(double d) {
        if (Double.isInfinite(d)) return "Infinity";
        if (d == (long) d) return String.format("%d", (long) d);
        return String.valueOf(d);
    }

    public static void main(String[] args) throws Exception {
        String path = "/tmp/…/graph.json";
        String json = Files.readString(Path.of(path));

        int nodesStartIndex = json.indexOf("\"nodes\": [") + 10;
        int nodesEndIndex = json.indexOf("]", nodesStartIndex);
        String nodesContent = json.substring(nodesStartIndex, nodesEndIndex);

        List<String> nodes = new ArrayList<>();
        if (!nodesContent.trim().isEmpty()) {
            String[] parts = nodesContent.split(",");
            for (String p : parts) {
                String name = p.trim().replace("\"", "");
                if (!name.isEmpty()) {
                    nodes.add(name);
                }
            }
        }

        int edgesStartIndex = json.indexOf("\"edges\": [") + 10;
        int edgesEndIndex = json.lastIndexOf("]");
        String edgesContent = json.substring(edgesStartIndex, edgesEndIndex);

        Map<String, List<Edge>> adj = new HashMap<>();
        for (String node : nodes) {
            adj.put(node, new ArrayList<>());
        }

        Pattern objectPattern = Pattern.compile("\\{[^\\}]*\\}");
        Matcher objectMatcher = objectPattern.matcher(edgesContent);

        Pattern fromPattern = Pattern.compile("\"from\"\\s*:\\s*\"([^\"]+)\"");
        Pattern toPattern = Pattern.compile("\"to\"\\s*:\\s*\"([^\"]+)\"");
        Pattern weightPattern = Pattern.compile("\"weight\"\\s*:\\s*([\\d.-]+)");

        while (objectMatcher.find()) {
            String obj = objectMatcher.group();
            String from = null, to = null;
            double weight = 0;

            Matcher m1 = fromPattern.matcher(obj);
            if (m1.find()) from = m1.group(1);
            Matcher m2 = toPattern.matcher(obj);
            if (m2.find()) to = m2.group(1);
            Matcher m3 = weightPattern.matcher(obj);
            if (m3.find()) weight = Double.parseDouble(m3.group(1));

            if (from != null && to != null) {
                if (adj.containsKey(from) && adj.containsKey(to)) {
                    adj.get(from).add(new Edge(to, weight));
                    adj.get(to).add(new Edge(from, weight));
                }
            }
        }

        Map<String, Double> distances = new HashMap<>();
        for (String node : nodes) {
            distances.put(node, Double.POSITIVE_INFINITY);
        }

        PriorityQueue<NodeDist> pq = new PriorityQueue<>();
        if (distances.containsKey("A")) {
            distances.put("A", 0.0);
            pq.add(new NodeDist("A", 0.0));
        }

        while (!pq.isEmpty()) {
            NodeDist current = pq.poll();
            if (current.dist > distances.get(current.name)) continue;

            for (Edge edge : adj.get(current.name)) {
                double newDist = current.dist + edge.weight;
                if (newDist < distances.get(edge.to)) {
                    distances.put(edge.to, newDist);
                    pq.add(new NodeDist(edge.to, newDist));
                }
            }
        }

        System.out.println("=== Shortest Paths from A ===");
        System.out.println();

        List<String> sortedNodes = new ArrayList<>(nodes);
        Collections.sort(sortedNodes);

        for (String node : sortedNodes) {
            System.out.println("A -> " + node + ": " + formatDistance(distances.get(node)));
        }
    }
}

import Foundation

func scalarToString(_ value: Any) -> String {
    if let s = value as? String { return "\"\(s)\"" }
    if let b = value as? Bool { return "\(b)" }
    if value is NSNull { return "null" }
    return "\(value)"
}

func areEqual(_ lhs: Any, _ rhs: Any) -> Bool {
    if lhs is NSNull || rhs is NSNull {
        return lhs is NSNull && rhs is NSNull
    }
    if let lDict = lhs as? [String: Any], let rDict = rhs as? [String: Any] {
        if lDict.count != rDict.count { return false }
        for (key, lVal) in lDict {
            guard let rVal = rDict[key] else { return false }
            if !areEqual(lVal, rVal) { return false }
        }
        return true
    }
    if let lArr = lhs as? [Any], let rArr = rhs as? [Any] {
        if lArr.count != rArr.count { return false }
        for i in 0..<lArr.count {
            if !areEqual(lArr[i], rArr[i]) { return false }
        }
        return true
    }
    return scalarToString(lhs) == scalarToString(rhs)
}

func merge(a: Any, b: Any) -> Any {
    if let dictA = a as? [String: Any], let dictB = b as? [String: Any] {
        var result = dictA
        for (key, valueB) in dictB {
            if let valueA = dictA[key] {
                result[key] = merge(a: valueA, b: valueB)
            } else {
                result[key] = valueB
            }
