use std::io::{Read, Write};
use std::net::TcpStream;

struct Product {
    name: String,
    price: f64,
}

fn main() {
    let mut stream = match TcpStream::connect("127.0.0.1:18923") {
        Ok(s) => s,
        Err(_) => return,
    };

    let request = "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n";
    if let Err(_) = stream.write_all(request.as_bytes()) {
        return;
    }

    let mut response = String::new();
    if let Err(_) = stream.read_to_string(&mut response) {
        return;
    }

    let mut body = "";
    if let Some(idx) = response.find("\r\n\r\n") {
        body = &response[idx + 4..];
    } else if let Some(idx) = response.find("\n\n") {
        body = &response[idx + 2..];
    }

    let mut products = Vec::new();
    let mut current_pos = 0;

    while let Some(start_idx) = body[current_pos..].find('{') {
        let absolute_start = current_pos + start_idx;
        if let Some(end_idx) = body[absolute_start..].find('}') {
            let absolute_end = absolute_start + end_idx;
            let object_str = &body[absolute_start..=absolute_end];

            let mut name = String::new();
            if let Some(n_idx) = object_str.find("\"name\"") {
                if let Some(colon_idx) = object_str[n_idx..].find(':') {
                    let after_colon = &object_str[n_idx + colon_idx + 1..];
                    if let Some(first_quote) = after_colon.find('"') {
                        let after_first_quote = &after_colon[first_quote + 1..];
                        if let Some(second_quote) = after_first_quote.find('"') {
                            name = after_first_quote[..second_quote].to_string();
                        }
                    }
                }
            }

            let mut price = 0.0;
            if let Some(p_idx) = object_str.find("\"price\"") {
                if let Some(colon_idx) = object_str[p_idx..].find(':') {
                    let after_colon = &object_str[p_idx + colon_idx + 1..];
                    let trimmed = after_colon.trim_start();
                    let mut price_str = String::new();
                    for c in trimmed.chars() {
                        if c.is_ascii_digit() || c == '.' || c == '-' {
                            price_str.push(c);
                        } else {
                            break;
                        }
                    }
                    if let Ok(p) = price_str.parse::<f64>() {
                        price = p;
                    }
                }
            }

            if !name.is_empty() {
                products.push(Product { name, price });
            }
            current_pos = absolute_end + 1;
        } else {
            break;
        }
    }

    let mut filtered: Vec<_> = products.into_iter().filter(|p| p.price > 50.0).collect();
    filtered.sort_by(|a, b| a.name.cmp(&b.name));

    println!("=== Filtered Products (price > $50.00) ===");
    println!();

    let mut total_price = 0.0;
    for p in &filtered {
        println!("{}: ${:.2}", p.name, p.price);
        total_price += p.price;
    }

    println!();
    println!("Count: {}", filtered.len());
    println!("Total: ${:.2}", total_price);
}

