import Foundation

struct GraphData: Codable {
    let nodes: [String]
    let edges: [Edge]
}

struct Edge: Codable {
    let from: String
    let to: String
    let weight: Double
}

struct PriorityQueueItem: Comparable {
    let node: String
    let distance: Double

    static func < (lhs: PriorityQueueItem, rhs: PriorityQueueItem) -> Bool {
        return lhs.distance < rhs.distance
    }
}

struct PriorityQueue {
    private var heap: [PriorityQueueItem] = []
    var isEmpty: Bool { return heap.isEmpty }

    mutating func push(_ item: PriorityQueueItem) {
        heap.append(item)
        var index = heap.count - 1
        while index > 0 {
            let parent = (index - 1) / 2
            if heap[index].distance < heap[parent].distance {
                heap.swapAt(index, parent)
                index = parent
            } else {
                break
            }
        }
    }

    mutating func pop() -> PriorityQueueItem? {
        if heap.isEmpty { return nil }
        if heap.count == 1 { return heap.removeFirst() }
        let top = heap[0]
        heap[0] = heap.removeLast()
        var index = 0
        while true {
            let left = 2 * index + 1
            let right = 2 * index + 2
            var smallest = index
            if left < heap.count && heap[left].distance < heap[smallest].distance {
                smallest = left
            }
            if right < heap.count && heap[right].distance < heap[smallest].distance {
                smallest = right
            }
            if smallest != index {
                heap.swapAt(index, smallest)
                index = smallest
            } else {
                break
            }
        }
        return top
    }
}

func solve() {
    let filePath = "/tmp/…/graph.json"

    guard let data = try? Data(contentsOf: URL(fileURLWithPath: filePath)),
          let graphData = try? JSONDecoder().decode(GraphData.self, from: data) else {
        return
    }

    var adj: [String: [(String, Double)]] = [:]
    for edge in graphData.edges {
        adj[edge.from, default: []].append((edge.to, edge.weight))
        adj[edge.to, default: []].append((edge.from, edge.weight))
    }

    var distances: [String: Double] = [:]
    for node in graphData.nodes {
        distances[node] = Double.infinity
    }

    if distances["A"] != nil {
        distances["A"] = 0.0
    }

    var pq = PriorityQueue()
    if distances["A"] != nil {
        pq.push(PriorityQueueItem(node: "A", distance: 0.0))
    }

    while let current = pq.pop() {
        if current.distance > (distances[current.node] ?? Double.infinity) {
            continue
        }

        if let neighbors = adj[current.node] {
            for (neighbor, weight) in neighbors {
                let newDist = current.distance + weight
                if newDist < (distances[neighbor] ?? Double.infinity) {
                    distances[neighbor] = newDist
                    pq.push(PriorityQueueItem(node: neighbor, distance: newDist))
                }
            }
        }
    }

    print("=== Shortest Paths from A ===")
    print("")
    let sortedNodes = graphData.nodes.sorted()
    for node in sortedNodes {
        if let dist = distances[node] {
            let distString: String
            if dist.isInfinite {
                distString = "inf"
            } else if dist.truncatingRemainder(dividingBy: 1) == 0 {
                distString = String(format: "%.0f", dist)
            } else {
                distString = String(dist)
            }
            print("A -> \(node): \(distString)")
        }
    }
}

solve()

import * as fs from 'fs';

class PriorityQueue<T> {
  private heap: { priority: number; value: T }[] = [];

  push(value: T, priority: number) {
    this.heap.push({ priority, value });
    this.bubbleUp();
  }

  pop(): { priority: number; value: T } | undefined {
    if (this.heap.length === 0) return undefined;
    if (this.heap.length === 1) return this.heap.pop();
    const top = this.heap[0];
    this.heap[0] = this.heap.pop()!;
    this.bubbleDown();
    return top;
  }

  size(): number {
    return this.heap.length;
  }

  private bubbleUp() {
    let idx = this.heap.length - 1;
    while (idx > 0) {
      let pIdx = Math.floor((idx - 1) / 2);
      if (this.heap[idx].priority >= this.heap[pIdx].priority) break;
      [this.heap[idx], this.heap[pIdx]] = [this.heap[pIdx], this.heap[idx]];
      idx = pidx;
    }
  }

  private bubbleUpManual() {
    let idx = this.heap.length - 1;
    while (idx > 0) {
      let pIdx = Math.floor((idx - 1) / 2);
      if (this.heap[idx].priority >= this.heap[pIdx].priority) break;
      [this.heap[idx], this.heap[pIdx]] = [this.heap[pIdx], this.heap[idx]];
      idx = pIdx;
    }
  }

  // Re-writing bubbleUp to be cleaner
  private bubbleUpClean() {
    let idx = this.heap.length - 1;
    while (idx > 0) {
      const pIdx = Math.floor((idx - 1) / 2);
      if (this.heap[idx].priority >= this.heap[pIdx].priority) break;
      [this.heap[idx], this.heap[pIdx]] = [this.heap[pIdx], this.heap[idx]];
      idx = pIdx;
    }
  }

  // Finalized PriorityQueue structure
  private bubbleUpFinal() {
    let idx = this.heap.length - 1;
    while (idx > 0) {
      const pIdx = Math.floor((idx - 1) / 2);
      if (this.heap[idx].priority >= this.heap[pIdx].priority) break;
      [this.heap[idx], this.heap[pIdx]] = [this.heap[pIdx], this.heap[idx]];
      idx = pIdx;
    }
  }
}

// Re-implementing to ensure no errors
class MinHeap<T> {
  private heap: { priority: number; value: T }[] = [];

  push(value: T, priority: number) {
    this.heap.push({ priority, value });
    this.bubbleUp();
  }

  pop(): { priority: number; value: T } | undefined {
    if (this.heap.length === 0) return undefined;
    if (this.heap.length === 1) return this.heap.pop();
    const top = this.heap[0];
    this.heap[0] = this.heap.pop()!;
    this.bubbleDown();
    return top;
  }

  size(): number {
    return this.heap.length;
  }

  private bubbleUp() {
    let idx = this.heap.length - 1;
    while (idx > 0) {
      const pIdx = Math.floor((idx - 1) / 2);
      if (this.heap[idx].priority >= this.heap[pIdx].priority) break;
      [this.heap[idx], this.heap[pIdx]] = [this.heap[pIdx], this.heap[idx]];
      idx = pIdx;
    }
  }

  private bubbleDown() {
    let idx = 0;
    while (true) {
      let l = 2 * idx + 1;
      let r = 2 * idx + 2;
      let s = idx;
      if (l < this.heap.length && this.heap[l].priority < this.heap[s].priority) s = l;
      if (r < this.heap.length && this.heap[r].priority < this.heap[s].priority) s = r;
      if (s === idx) break;
      [this.heap[idx], this.heap[s]] = [this.heap[s], this.heap[idx]];
      idx = s;
    }
  }
}

function solve() {
  const filePath = '/tmp/…/graph.json';
  const rawData = fs.readFileSync(filePath, 'utf8');
  const data = JSON.parse(rawData);

  const nodes: string[] = data.nodes;
  const edges: any[] = data.edges;

  const adj = new Map<string, { node: string, weight: number }[]>();
  for (const node of nodes) {
    adj.set(node, []);
  }

  for (const edge of edges) {
    adj.get(edge.from)?.push({ node: edge.to, weight: edge.weight });
    adj.get(edge.to)?.push({ node: edge.from, weight: edge.weight });
  }

  const distances = new Map<string, number>();
  for (const node of nodes) {
    distances.set(node, Infinity);
  }

  const pq = new MinHeap<string>();

  if (nodes.includes("A")) {
    distances.set("A", 0);
    pq.push("A", 0);
  }

  while (pq.size() > 0) {
    const current = pq.pop();
    if (!current) break;
    const u = current.value;
    const d = current.priority;

    if (d > (distances.get(u) ?? Infinity)) continue;

    const neighbors = adj.get(u) || [];
    for (const neighbor of neighbors) {
      const newDist = d + neighbor.weight;
      if (newDist < (distances.get(neighbor.node) ?? Infinity)) {
        distances.set(neighbor.node, newDist);
        pq.push(neighbor.node, newDist);
      }
    }
  }

  console.log("=== Shortest Paths from A ===\n");
  const sortedNodes = [...nodes].sort();
  for (const node of sortedNodes) {
    const dist = distances.get(node);
    console.log(`A -> ${node}: ${dist}`);
  }
}

solve();

