import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) {
        String filePath = "/tmp/…/app.log";
        TreeMap<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> componentErrorCounts = new HashMap<>();
        TreeSet<String> errorMessages = new TreeSet<>();
        Map<Integer, Integer> hourCounts = new HashMap<>();

        Pattern pattern = Pattern.compile("^\\[\\d{4}-\\d{2}-\\d{2} (\\d{2}):\\d{2}:\\d{2}\\] (\\w+) \\(([^)]+)\\) - (.*)$");

        try (BufferedReader reader = Files.newBufferedReader(Paths.get(filePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                Matcher matcher = pattern.matcher(line);
                if (matcher.find()) {
                    int hour = Integer.parseInt(matcher.group(1));
                    String level = matcher.group(2);
                    String component = matcher.group(3);
                    String message = matcher.group(4);

                    levelCounts.put(level, levelCounts.getOrDefault(level, 0) + 1);
                    hourCounts.put(hour, hourCounts.getOrDefault(hour, 0) + 1);

                    if ("ERROR".equals(level)) {
                        componentErrorCounts.put(component, componentErrorCounts.getOrDefault(component, 0) + 1);
                        errorMessages.add(message);
                    }
                }
            }
        } catch (IOException e) {
            // Handle error if necessary
        }

        System.out.println("=== Log Analysis ===");
        System.out.println();
        System.out.println("Entries by Level:");
        for (Map.Entry<String, Integer> entry : levelCounts.entrySet()) {
            System.out.println("  " + entry.getKey() + ": " + entry.getValue());
        }
        System.out.println();

        String mostErrorComp = "";
        int maxErrors = -1;
        List<String> sortedComponents = new ArrayList<>(componentErrorCounts.keySet());
        Collections.sort(sortedComponents);
        for (String comp : sortedComponents) {
            int count = componentErrorCounts.get(comp);
            if (count > maxErrors) {
                maxErrors = count;
                mostErrorComp = comp;
            }
        }
        if (maxErrors != -1) {
            System.out.println("Component with Most Errors: " + mostErrorComp + " (" + maxErrors + " errors)");
        }
        System.out.println();

        System.out.println("Unique Error Messages:");
        for (String msg : errorMessages) {
            System.out.println("  - " + msg);
        }
        System.out.println();

        int busiestHour = -1;
        int maxEntries = -1;
        List<Integer> sortedHours = new ArrayList<>(hourCounts.keySet());
        Collections.sort(sortedHours);
        for (int hour : sortedHours) {
            int count = hourCounts.get(hour);
            if (count > maxEntries) {
                maxEntries = count;
                busiestHour = hour;
            }
        }
        if (busiestHour != -1) {
            System.out.printf("Busiest Hour: %02d:00 (%d entries)%n", busiestHour, maxEntries);
        }
    }
}

