    for (int i = 0; i < j->obj.size - 1; i++) {
        for (int k = 0; k < j->obj.size - i - 1; k++) {
            if (strcmp(j->obj.keys[k], j->obj.keys[k + 1]) > 0) {
                char* tk = j->obj.keys[k]; j->obj.keys[k] = j->obj.keys[k + 1]; j->obj.keys[k + 1] = tk;
                Json* tv = j->obj.vals[k]; j->obj.vals[k] = j->obj.vals[k + 1]; j->obj.vals[k + 1] = tv;
            }
        }
    }
}

Json* merge_json(const Json* a, const Json* b) {
    if (a->type == T_OBJECT && b->type == T_OBJECT) {
        Json* res = copy_json(a);
        for (int i = 0; i < b->obj.size; i++) {
            int idx = -1;
            for (int j = 0; j < res->obj.size; j++) {
                if (strcmp(res->obj.keys[j], b->obj.keys[i]) == 0) { idx = j; break; }
            }
            if (idx != -1) {
                if ((res->obj.vals[idx]->type == T_OBJECT && b->obj.vals[i]->type == T_OBJECT) ||
                    (res->obj.vals[idx]->type == T_ARRAY && b->obj.vals[i]->type == T_ARRAY)) {
                    Json* m = merge_json(res->obj.vals[idx], b->obj.vals[i]);
                    free_json(res->obj.vals[idx]);
                    res->obj.vals[idx] = m;
                } else {
                    free_json(res->obj.vals[idx]);
                    res->obj.vals[idx] = copy_json(b->obj.vals[i]);
                }
            } else {
                res->obj.keys = realloc(res->obj.keys, sizeof(char*) * (res->obj.size + 1));
                res->obj.vals = realloc(res->obj.vals, sizeof(Json*) * (res->obj.size + 1));
                res->obj.keys[res->obj.size] = strdup(b->obj.keys[i]);
                res->obj.vals[res->obj.size] = copy_json(b->obj.vals[i]);
                res->obj.size++;
            }
        }
        sort_obj(res);
        return res;
    } else if (a->type == T_ARRAY && b->type == T_ARRAY) {
        Json* res = create_json(T_ARRAY);
        for (int i = 0; i < a->arr.size; i++) {
            res->arr.els = realloc(res->arr.els, sizeof(Json*) * (res->arr.size + 1));
            res->arr.els[res->arr.size++] = copy_json(a->arr.els[i]);
        }
        for (int i = 0; i < b->arr.size; i++) {
            bool exists = false;
            for (int j = 0; j < res->arr.size; j++) {
                if (json_eq(res->arr.els[j], b->arr.els[i])) { exists = true; break; }
            }
            if (!exists) {
                res->arr.els = realloc(res->arr.els, sizeof(Json*) * (res->arr.size + 1));
                res->arr.els[res->arr.size++] = copy_json(b->arr.els[i]);
            }
        }
        return res;
    }
    return copy_json(b);
}

char* get_string(const char** s) {
    (*s)++; 
    size_t cap = 256, len = 0;
    char* buf = malloc(cap);
    while (**s && **s != '"') {
        if (**s == '\\') {
            (*s)++;
            if (**s == '\0') break;
            char c = **s;
            if (c == 'b') c = '\b'; else if (c == 'f') c = '\f';
            else if (c == 'n') c = '\n'; else if (c == 'r') c = '\r';
            else if (c == 't') c = '\t';
            else if (c == '"') c = '"'; else if (c == '\\') c = '\\';
            if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
            buf[len++] = c;
            (*s)++;
        } else {
            if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
            buf[len++] = **s;
            (*s)++;
        }
    }
    buf[len] = '\0';
    if (**s == '"') (*s)++;
    return buf;
}

Json* parse_json(const char** s) {
    while (**s && isspace((unsigned char)*(*s))) (*s)++;
    if (**s == '\0') return NULL;
    if (**s == '{') {
        Json* obj = create_json(T_OBJECT);
        (*s)++;
        while (1) {
            while (**s && isspace((unsigned char)*(*s))) (*s)++;
            if (**s == '}') { (*s)++; break; }
            char* key = get_string(s);
            while (**s && isspace((unsigned char)*(*s))) (*s)++;
            if (**s == ':') (*s)++;
            Json* val = parse_json(s);
            obj->obj.keys = realloc(obj->obj.keys, sizeof(char*) * (obj->obj.size + 1));
            obj->obj.vals = realloc(obj->obj.vals, sizeof(Json*) * (obj->obj.size + 1));
            obj->obj.keys[obj->obj.size] = key;
            obj->obj.vals[obj->obj.size++] = val;
            while (**s && isspace((unsigned char)*(*s))) (*s)++;
            if (**s == ',') (*s)++;
            while (**s && isspace((unsigned char)*(*s))) (*s)++;
            if (**s == '}') { (*s)++; break; }
        }
        sort_obj(obj);
        return obj;
    } else if (**s == '[') {
        Json* arr = create_json(T_ARRAY);
        (*s)++;
        while (1) {
            while (**s && isspace((unsigned char)*(*s))) (*s)++;
            if (**s == ']') { (*s)++; break; }
            Json* val = parse_json(s);
            arr->arr.els = realloc(arr->arr.els, sizeof(Json*) * (arr->arr.size + 1));
            arr->arr.els[arr->arr.size++] = val;
            while (**s && isspace((unsigned char)*(*s))) (*s)++;
            if (**s == ',') (*s)++;
            if (**s == ']') { (*s)++; break; }
        }
        return arr;
    } else if (**s == '"') {
        Json* str = create_json(T_STRING);
        str->s = get_string(s);
        return str;
    } else if (isdigit(**s) || **s == '-') {
        Json* num = create_json(T_NUMBER);
        char* end;
        num->n = strtod(*s, &end);
        *s = end;
        return num;
    } else {
        while (**s && isspace((unsigned char)*(*s))) (*s)++;
        if (strncmp(*s, "true", 4) == 0) { Json* b = create_json(T_BOOL); b->b = true; *s += 4; return b; }
        else if (strncmp(*s, "false", 5) == 0) { Json* b = create_json(T_BOOL); b->b = false; *s += 5; return b; }
        else if (strncmp(*s, "null", 4) == 0) { *s += 4; return create_json(T_NULL); }
    }
    return NULL;
}

void print_json(const Json* j, int indent) {
    if (j->type == T_NULL) { printf("null"); return; }
    if (j->type == T_BOOL) { printf("%s", j->b ? "true" : "false"); return; }
    if (j->type == T_NUMBER) { printf("%g", j->n); return; }
    if (j->type == T_STRING) { printf("\"%s\"", j->s); return; }
    if (j->type == T_ARRAY) {
        printf("[\n");
        for (int i = 0; i < j->arr.size; i++) {
            for (int k = 0; k < indent + 1; k++) printf("  ");
            print_json(j->arr.els[i], indent + 1);
            if (i < j->arr.size - 1) printf(",");
            printf("\n");
        }
        for (int k = 0; k < indent; k++) printf("  ");
        printf("]");
        return;
    }
    if (j->type == T_OBJECT) {
        printf("{\n");
        for (int i = 0; i < j->obj.size; i++) {
            for (int k = 0; k < indent + 1; k++) printf("  ");
            printf("\"%s\": ", j->obj.keys[i]);
            print_json(j->obj.vals[i], indent + 1);
            if (i < j->obj.size - 1) printf(",");
            printf("\n");
        }
        for (int k = 0; k < indent; k++) printf("  ");
        printf("}");
        return;
    }
}

char* read_file(const char* path) {
    FILE* f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    char* buf = malloc(len + 1);
    if (buf) {
        fread(buf, 1, len, f);
        buf[len] = '\0';
    }
    fclose(f);
    return buf;
}

int main() {
    const char* path_a = "/tmp/…/config_a.json";
    const char* path_b = "/tmp/…/config_b.json";
    char* buf_a = read_file(path_a);
    char* buf_b = read_file(path_b);
    if (!buf_a || !buf_b) {
        if (buf_a) free(buf_a);
        if (buf_b) free(buf_b);
        return 0;
    }
    const char *s_a = buf_a, *s_b = buf_b;
    Json* json_a = parse_json(&s_a);
    Json* json_b = parse_json(&s_b);
    Json* merged = merge_json(json_a, json_b);
    print_json(merged, 0);
    printf("\n");
    free_json(json_a);
    free_json(json_b);
    free_json(merged);
    free(buf_a);
    free(buf_b);
    return 0;
}

use std::collections::{HashMap, BinaryHeap};
use std::cmp::Ordering;
use std::fs;

#[derive(Eq, PartialEq)]
struct State {
    cost: u64,
    node: String,
}

impl Ord for State {
    fn cmp(&self, other: &Self) -> Ordering {
        other.cost.cmp(&self.cost)
    }
}

impl PartialOrd for State {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn main() {
    let path = "/tmp/…/graph.json";
    let json = match fs::read_to_string(path) {
        Ok(content) => content,
        Err(_) => return,
    };

    let nodes_start = match json.find("\"nodes\": [") {
        Some(idx) => idx + 10,
        None => return,
    };
    let nodes_end = match json.find("]") {
        Some(idx) => idx,
        None => return,
    };
    let nodes_str = &json[nodes_start..nodes_end];

    let mut nodes = Vec::new();
    for part in nodes_str.split(',') {
        let trimmed = part.trim().trim_matches('"');
        if !trimmed.is_empty() {
            nodes.push(trimmed.to_string());
        }
    }

    let edges_start = match json.find("\"edges\": [") {
        Some(idx) => idx + 10,
        None => return,
    };
    let edges_end = match json.rfind(']') {
        Some(idx) => idx,
        None => return,
    };
    let edges_str = &json[edges_start..edges_end];

    let mut adj = HashMap::new();
    for part in edges_str.split('}') {
        let part = part.trim();
        if !part.contains('{') {
            continue;
        }
        let clean_part = part.trim_start_matches('{');

        let mut from = String::new();
        let mut to = String::new();
        let mut weight = 0;

        for item in clean_part.split(',') {
            let item = item.trim();
            if item.contains("\"from\"") {
                let val = item.split(':').nth(1).unwrap_or("").trim().trim_matches('"');
                from = val.to_string();
            } else if item.contains("\"to\"") {
                let val = item.split(':').nth(1).unwrap_or("").trim().trim_matches('"');
                to = val.to_string();
            } else if item.contains("\"weight\"") {
                let val = item.split(':').nth(1).unwrap_or("").trim();
                weight = val.parse::<u64>().unwrap_or(0);
            }
        }
        if !from.is_empty() && !to.is_empty() {
            adj.entry(from.clone()).or_insert_with(Vec::new).push((to.clone(), weight));
            adj.entry(to.clone()).or_insert_with(Vec::new).push((from.clone(), weight));
        }
    }

    let mut dists = HashMap::new();
    for node in &nodes {
        dists.insert(node.clone(), u64::MAX);
    }
    dists.insert("A".to_string(), 0);

    let mut pq = BinaryHeap::new();
    pq.push(State {
        cost: 0,
        node: "A".to_string(),
    });

    while let Some(State { cost, node }) = pq.pop() {
        if cost > *dists.get(&node).unwrap_or(&u64::MAX) {
            continue;
        }
        if let Some(neighbors) = adj.get(&node) {
            for (next_node, weight) in neighbors {
                let next_cost = cost + weight;
                if next_cost < *dists.get(next_node).unwrap_or(&u64::MAX) {
                    dists.insert(next_node.clone(), next_cost);
                    pq.push(State {
                        cost: next_cost,
                        node: next_node.clone(),
                    });
                }
            }
        }
    }

    println!("=== Shortest Paths from A ===");
    println!();
    let mut sorted_nodes = nodes.clone();
    sorted_nodes.sort();
    for node in sorted_nodes {
        if let Some(&d) = dists.get(&node) {
            println!("A -> {}: {}", node, d);
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/**
 * Executes a shell command and returns the output as a dynamically allocated string.
 * The trailing newline and whitespace are stripped.
 */
char* execute_command(const char* cmd) {
    char* buffer = (char*)malloc(1024);
    if (!buffer) return NULL;
    memset(buffer, 0, 1024);

    FILE* fp = popen(cmd, "r");
    if (!fp) {
        free(buffer);
        return NULL;
    }

    // Read the first line of output
    if (fgets(buffer, 1024, fp) == NULL) {
        pclose(fp);
        buffer[0] = '\0';
        return buffer;
    }

    pclose(fp);

    // Strip trailing newline, carriage return, or whitespace
    size_t len = strlen(buffer);
    while (len > 0 && (buffer[len - 1] == '\n' || buffer[len - 1] == '\r' || buffer[len - 1] == ' ')) {
        buffer[len - 1] = '\0';
        len--;
    }

    return buffer;
}

int main(void) {
    // Capture command outputs
    char* hostname = execute_command("hostname");
    char* os = execute_command("uname -s");
    char* architecture = execute_command("uname -m");
    char* username = execute_command("whoami");

    // Output the JSON object with the specified key order and 2-space indentation
    printf("{\n");
    printf("  \"hostname\": \"%s\",\n", hostname ? hostname : "");
    printf("  \"os\": \"%s\",\n", os ? os : "");
    printf("  \"architecture\": \"%s\",\n", architecture ? architecture : "");
    printf("  \"username\": \"%s\"\n", username ? username : "");
    printf("}\n");

    // Cleanup allocated memory
    if (hostname) free(hostname);
    if (os) free(os);
    if (architecture) free(architecture);
    if (username) free(username);

    return 0;
}

use std::collections::BTreeMap;
use std::fs;
use std::io;
use std::path::Path;

struct FileInfo {
    rel_path: String,
    lines: usize,
    chars: usize,
}

fn walk_dir(
    dir: &Path,
    root: &Path,
    extension_map: &mut BTreeMap<String, Vec<FileInfo>>,
    total_files: &mut usize,
    total_lines: &mut usize,
    total_chars: &mut usize,
) -> io::Result<()> {
    if !dir.is_dir() {
        return Ok(());
    }

    let entries = fs::read_dir(dir)?;

    for entry in entries {
        let entry = entry?;
        let path = entry.path();
        let file_type = entry.file_type()?;

        if file_type.is_dir() {
            if !file_type.is_symlink() {
                walk_dir(&path, root, extension_map, total_files, total_lines, total_chars)?;
            }
        } else if file_type.is_file() {
            if !file_type.is_symlink() {
                let content = fs::read(&path)?;
                let chars = content.len();
                let mut lines = 0;
                if !content.is_empty() {
                    let mut count = content.split(|&b| b == b'\n').count();
                    if content.ends_with(&[b'\n']) {
                        count -= 1;
                    }
                    lines = count;
                }

                let ext = match path.extension().and_then(|s| s.to_str()) {
                    Some(s) => format!(".{}", s),
                    None => "".to_string(),
                };

                let rel_path = path.strip_prefix(root)
                    .unwrap_or(&path)
                    .to_str()
                    .unwrap_or("")
                    .to_string();

                extension_map
                    .entry(ext)
                    .or_insert_with(Vec::new)
                    .push(FileInfo {
                        rel_path,
                        lines,
                        chars,
                    });

                *total_files += 1;
                *total_lines += lines;
                *total_chars += chars;
            }
        }
    }
    Ok(())
}

fn main() {
    let root_str = "/tmp/…/project_tree";
    let root_path = Path::new(root_str);

    let mut extension_map: BTreeMap<String, Vec<FileInfo>> = BTreeMap::new();
    let mut total_files = 0;
    let mut total_lines = 0;
    let mut total_chars = 0;

    let _ = walk_dir(root_path, root_path, &mut extension_map, &mut total_files, &mut total_lines, &mut total_chars);

    println!("=== File Tree Analysis ===");
    println!();

    for (ext, mut files) in extension_map {
        files.sort_by(|a, b| a.rel_path.cmp(&b.rel_path));

        let ext_files = files.len();
        let mut ext_lines = 0;
        let mut ext_chars = 0;

        for file in &files {
            ext_lines += file.lines;
            ext_chars += file.chars;
        }

        println!("Extension: {}", ext);
        println!("  Files: {}", ext_files);
        println!("  Total Lines: {}", ext_lines);
        println!("  Total Characters: {}", ext_chars);

        for file in &files {
            println!("    {}: {} lines, {} chars", file.rel_path, file.lines, file.chars);
        }
    }

    println!();
    println!("Total: {} files, {} lines, {} characters", total_files, total_lines, total_chars);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char name[256];
    double total_salary;
    int count;
} Dept;

void print_comma_formatted(char* s) {
    int dot_pos = -1;
    int len = strlen(s);
    for (int i = s[0] == '-' ? 1 : 0; i < len; i++) {
        if (s[i] == '.') {
            dot_pos = i;
            break;
        }
    }
    if (dot_pos == -1) dot_pos = len;

    int start_idx = (s[0] == '-') ? 1 : 0;

    for (int i = 0; i < len; i++) {
        if (i >= start_idx && dot_pos != -1 && (dot_pos - i) % 3 == 0 && i > 0 && i < dot_pos) {
            printf(",");
        }
        printf("%c", s[i]);
    }
}

int compare_depts(const void* a, const void* b) {
    return strcmp(((Dept*)a)->name, ((Dept*)b)->name);
}

int main(void) {
    const char* filename = "/tmp/…/employees.csv";
    FILE* fp = fopen(filename, "r");
    if (!fp) return 0;

    char line[1024];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return 0;
    }

    Dept* departments = NULL;
    int dept_count = 0;
    double total_budget = 0;
    double highest_salary = -1.0;
    char highest_name[256] = "";

    while (fgets(line, sizeof(line), fp)) {
        line[strcspn(line, "\r\n")] = 0;
        char* tokens[6];
        int t = 0;
        char* ptr = line;

        // Manual CSV parsing to handle potential empty fields or quotes
        // But for this specific task, strtok is sufficient for the given columns
        char* token = strtok(line, ",");
        while (token != NULL && t < 6) {
            tokens[t++] = token;
            token = strtok(NULL, ",");
        }

        if (t < 4) continue;

        char* name = tokens[1];
        char* dept_name = tokens[2];
        double salary = atof(tokens[3]);

        total_budget += salary;

        if (salary > highest_salary) {
            highest_salary = salary;
            strncpy(highest_name, name, 255);
        }

        int found = -1;
        for (int i = 0; i < dept_count; i++) {
            if (strcmp(departments[i].name, dept_name) == 0) {
                found = i;
                break;
            }
        }

        if (found != -1) {
            departments[found].total_salary += salary;
            departments[found].count++;
        } else {
            dept_count++;
            departments = realloc(departments, sizeof(Dept) * dept_count);
            strncpy(departments[dept_count - 1].name, dept_name, 255);
            departments[dept_count - 1].total_salary = salary;
            departments[dept_count - 1].count = 1;
        }
    }
    fclose(fp);

    qsort(departments, dept_count, sizeof(Dept), compare_depts);

    printf("=== Salary Report ===\n\n");

    printf("Average Salary by Department:\n");
    for (int i = 0; i < dept_count; i++) {
        double avg = departments[i].total_salary / departments[i].count;
        printf("  %s: $", departments[i].name);
        char buf[64];
        sprintf(buf, "%.2f", avg);
        print_comma_formatted(buf);
        printf("\n");
    }

    printf("\nHighest Paid: %s ($,", highest_name);
    char h_buf[64];
    sprintf(h_buf, "%.0f", highest_salary);
    print_comma_formatted(h_buf);
    printf(")\n\n");

    printf("Departments with >2 employees:\n");
    for (int i = 0; i < dept_count; i++) {
        if (departments[i].count > 2) {
            printf("  %s (%d employees)\n", departments[i].name, departments[i].count);
        }
    }

    printf("\nTotal Budget: $");
    char b_buf[64];
    sprintf(b_buf, "%.0f", total_budget);
    print_comma_formatted(b_buf);
    printf("\n");

    free(departments);
    return 0;
}

