#include <stdio.h>

int main(void) {
    // 1. Define Matrix A
    int A[3][3] = {
        {1, 2, 3},
        {4, 5, 6},
        {7, 8, 9}
    };

    // 2. Define Matrix B
    int B[3][3] = {
        {9, 8, 7},
        {6, 5, 4},
        {3, 2, 1}
    };

    // 3. Compute C = A x B
    int C[3][3] = {0};
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            for (int k = 0; k < 3; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }

    // 4. Compute the determinant of C
    // Using Laplace expansion for a 3x3 matrix
    long long det = (long long)C[0][0] * (C[1][1] * C[2][2] - C[1][2] * C[2][1])
                  - (long long)C[0][1] * (C[1][0] * C[2][2] - C[1][2] * C[2][0])
                  + (long long)C[0][2] * (C[1][0] * C[2][1] - C[1][1] * C[2][0]);

    // Output in the exact specified format
    printf("=== Matrix Operations ===\n\n");

    printf("Matrix A:\n");
    for (int i = 0; i < 3; i++) {
        printf("  %4d %4d %4d\n", A[i][0], A[i][1], A[i][2]);
    }

    printf("\nMatrix B:\n");
    for (int i = 0; i < 3; i++) {
        printf("  %4d %4d %4d\n", B[i][0], B[i][1], B[i][2]);
    }

    printf("\nA x B =\n");
    for (int i = 0; i < 3; i++) {
        printf("  %4d %4d %4d\n", C[i][0], C[i][1], C[i][2]);
    }

    printf("\nDeterminant: %lld\n", det);

    return 0;
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[][] A = {
            {1, 2, 3},
            {4, 5, 6},
            {7, 8, 9}
        };
        int[][] B = {
            {9, 8, 7},
            {6, 5, 4},
            {3, 2, 1}
        };

        int[][] C = multiply(A, B);
        long detC = determinant(C);

        System.out.println("=== Matrix Operations ===");
        System.out.println();
        System.out.println("Matrix A:");
        printMatrix(A);
        System.out.println();
        System.out.println("Matrix B:");
        printMatrix(B);
        System.out.println();
        System.out.println("A x B =");
        printMatrix(C);
        System.out.println();
        System.out.println("Determinant: " + detC);
    }

    private static int[][] multiply(int[][] A, int[][] B) {
        int n = A.length;
        int m = B[0].length;
        int p = B.length;
        int[][] C = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                for (int k = 0; k < p; k++) {
                    C[i][j] += A[i][k] * B[k][j];
                }
            }
        }
        return C;
    }

    private static long determinant(int[][] matrix) {
        int n = matrix.length;
        if (n == 1) return matrix[0][0];
        if (n == 2) {
            return (long) matrix[0][0] * matrix[1][1] - (long) matrix[0][1] * matrix[1][0];
        }

        // 3x3 determinant using expansion
        long det = (long) matrix[0][0] * (matrix[1][1] * (long) matrix[2][2] - matrix[1][2] * (long) matrix[2][1])
                 - (long) matrix[0][1] * (matrix[1][0] * (long) matrix[2][2] - matrix[1][2] * (long) matrix[2][0])
                 + (long) matrix[0][2] * (matrix[1][0] * (long) matrix[2][1] - matrix[1][1] * (long) matrix[2][0]);
        return det;
    }

    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            System.out.print("  ");
            for (int i = 0; i < row.length; i++) {
                System.out.printf("%4d", row[i]);
                if (i < row.length - 1) {
                    System.out.print(" ");
                }
            }
            System.out.println();
        }
    }
}

#include <stdio.h>
