#define INF INT_MAX

typedef struct {
    int to;
    int weight;
} Edge;

typedef struct {
    Edge *edges;
    int size;
    int capacity;
} AdjList;

typedef struct {
    int node_idx;
    int dist;
} HeapNode;

typedef struct {
    HeapNode *data;
    int size;
    int capacity;
} MinHeap;

void swap(HeapNode *a, HeapNode *b) {
    HeapNode temp = *a;
    *a = *b;
    *b = temp;
}

void push(MinHeap *heap, int node_idx, int dist) {
    if (heap->size == heap->capacity) return;
    heap->data[heap->size].node_idx = node_idx;
    heap->data[heap->size].dist = dist;
    int i = heap->size++;
    while (i > 0 && heap->data[i].dist < heap->data[(i - 1) / 2].dist) {
        swap(&heap->data[i], &heap->data[(i - 1) / 2]);
        i = (i - 1) / 2;
    }
}

HeapNode pop(MinHeap *heap) {
    HeapNode res = heap->data[0];
    heap->data[0] = heap->data[--heap->size];
    int i = 0;
    while (i * 2 + 1 < heap->size) {
        int j = i * 2 + 1;
        if (j + 1 < heap->size && heap->data[j + 1].dist < heap->data[j].dist) j++;
        if (heap->data[i].dist <= heap->data[j].dist) break;
        swap(&heap->data[i], &heap->data[j]);
        i = j;
    }
    return res;
}

