            if (!obj_end || obj_end >= edges_end) break;

            char *from_key = strstr(obj_start, "\"from\":\"");
            char *to_key = strstr(obj_start, "\"to\":\"");
            char *weight_key = strstr(obj_start, "\"weight\":");

            if (from_key && to_key && weight_key) {
                char *f_q1 = strchr(from_key, '"') + 1;
                char *f_q2 = strchr(f_q1, '"');
                int f_len = f_q2 - f_q1;
                char from_name[1024] = {0};
                strncpy(from_name, f_q1, f_len);

                char *t_q1 = strchr(to_key, '"') + 1;
                char *t_q2 = strchr(t_q1, '"');
                int t_len = t_q2 - t_q1;
                char to_name[1024] = {0};
                strncpy(to_name, t_q1, t_len);

                int weight = 0;
                sscanf(weight_key, "\"weight\":%d", &weight);

                int from_idx = -1, to_idx = -1;
                for (int i = 0; i < num_nodes; i++) {
                    if (strcmp(node_names[i], from_name) == 0) from_idx = i;
                    if (strcmp(node_names[i], to_name) == 0) to_idx = i;
                }

                if (from_idx != -1 && to_idx != -1) {
                    if (adj[from_idx].size == adj[from_idx].capacity) {
                        adj[from_idx].capacity = adj[from_idx].capacity == 0 ? 4 : adj[from_idx].capacity * 2;
                        adj[from_idx].edges = realloc(adj[from_idx].edges, sizeof(Edge) * adj[from_idx].capacity);
                    }
                    adj[from_idx].edges[adj[from_idx].size++] = (Edge){to_idx, weight};

                    if (adj[to_idx].size == adj[to_idx].capacity) {
                        adj[to_idx].capacity = adj[to_idx].capacity == 0 ? 4 : adj[to_idx].capacity * 2;
                        adj[to_idx].edges = realloc(adj[to_idx].edges, sizeof(Edge) * adj[to_idx].capacity);
                    }
                    adj[to_idx].edges[adj[to_idx].size++] = (Edge){from_idx, weight};
                }
            }
            p = obj_end + 1;
        }
    }

    int source_idx = -1;
    for (int i = 0; i < num_nodes; i++) {
        if (strcmp(node_names[i], "A") == 0) {
            source_idx = i;
            break;
        }
    }

    int *dist = malloc(sizeof(int) * num_nodes);
    for (int i = 0; i < num_nodes; i++) dist[i] = INF;
    if (source_idx != -1) {
        dist[source_idx] = 0;
        MinHeap pq;
        pq.data = malloc(sizeof(HeapNode) * (num_nodes * num_nodes + 1));
        pq.size = 0;
        pq.capacity = num_nodes * num_nodes + 1;
        push(&pq, source_idx, 0);

        while (pq.size > 0) {
            HeapNode top = pop(&pq);
            if (top.dist > dist[top.node_idx]) continue;
            for (int i = 0; i < adj[top.node_idx].size; i++) {
                int v = adj[top.node_idx].edges[i].to;
                int w = adj[top.node_idx].edges[i].weight;
                if (dist[top.node_idx] + w < dist[v]) {
                    dist[v] = dist[top.node_idx] + w;
                    push(&pq, v, dist[v]);
                }
            }
        }
        free(pq.data);
    }

    printf("=== Shortest Paths from A ===\n\n");

    // For output, we need to sort the nodes alphabetically by name.
