    int *indices = malloc(sizeof(int) * num_nodes);
    for (int i = 0; i < num_nodes; i++) indices[i] = i;

    // Sort indices based on node_names
    for (int i = 0; i < num_nodes - 1; i++) {
        for (int j = 0; j < num_nodes - i - 1; j++) {
            if (strcmp(node_names[indices[j]], node_names[indices[j+1]]) > 0) {
                int temp = indices[j];
                indices[j] = indices[j+1];
                indices[j+1] = temp;
            }
        }
    }

    for (int i = 0; i < num_nodes; i++) {
        int idx = indices[i];
        printf("A -> %s: %d\n", node_names[idx], dist[idx]);
    }

    // Cleanup
    for (int i = 0; i < num_nodes; i++) {
        free(node_names[i]);
        if (adj[i].edges) free(adj[i].edges);
    }
    free(node_names);
    free(adj);
    free(dist);
    free(indices);
    free(buffer);

    return 0;
}

