import * as fs from 'fs';

const filePath = '/tmp/…/app.log';

function solve() {
  let content = '';
  try {
    content = fs.readFileSync(filePath, 'utf8');
  } catch (e) {
    return;
  }

  const lines = content.split(/\r?\n/);
  const levelCounts: Record<string, number> = {};
  const errorComponentCounts: Record<string, number> = {};
  const errorMessages = new Set<string>();
  const hourCounts: Record<string, number> = {};

  for (const line of lines) {
    if (!line.trim()) continue;

    const match = line.match(/^\[\d{4}-\d{2}-\d{2} (\d{1,2}):\d{2}:\d{2}\] (\w+) \((\w+)\) - (.*)$/);
    if (match) {
      const hour = match[1].padStart(2, '0');
      const level = match[2];
      const component = match[3];
      const message = match[4];

      levelCounts[level] = (levelCounts[level] || 0) + 1;

      if (level === 'ERROR') {
        errorComponentCounts[component] = (errorComponentCounts[component] || 0) + 1;
        errorMessages.add(message);
      }

      hourCounts[hour] = (hourCounts[hour] || 0) + 1;
    }
  }

  console.log('=== Log Analysis ===');
  console.log('');

  console.log('Entries by Level:');
  const sortedLevels = Object.keys(levelCounts).sort();
  for (const level of sortedLevels) {
    console.log(`  ${level}: ${levelCounts[level]}`);
  }
  console.log('');

  let maxErrors = 0;
  let mostErrorComponent = '';
  const sortedComponents = Object.keys(errorComponentCounts).sort();
  for (const comp of sortedComponents) {
    if (errorComponentCounts[comp] > maxErrors) {
      maxErrors = errorComponentCounts[comp];
      mostErrorComponent = comp;
    }
  }
  console.log(`Component with Most Errors: ${mostErrorComponent} (${maxErrors} errors)`);
  console.log('');

  console.log('Unique Error Messages:');
  const sortedErrorMessages = Array.from(errorMessages).sort();
  for (const msg of sortedErrorMessages) {
    console.log(`  - ${msg}`);
  }
  console.log('');

  let maxEntries = 0;
  let busiestHour = '';
  const sortedHours = Object.keys(hourCounts).sort();
  for (const hour of sortedHours) {
    if (hourCounts[hour] > maxEntries) {
      maxEntries = hourCounts[hour];
      busiestHour = hour;
    }
  }
  if (busiestHour) {
    console.log(`Busiest Hour: ${busiestHour}:00 (${maxEntries} entries)`);
  }
}

