            char *rel_start = path + strlen(root_path);
            if (*rel_start == '/') rel_start++;
            new_file.rel_path = strdup(rel_start);

            FILE *fp = fopen(path, "rb");
            if (fp) {
                long l_count = 0;
                long c_count = 0;
                int c;
                while ((c = fgetc(fp)) != EOF) {
                    c_count++;
                    if (c == '\n') l_count++;
                }
                new_file.lines = l_count;
                new_file.chars = c_count;
                fclose(fp);
            } else {
                new_file.lines = 0;
                new_file.chars = 0;
            }

            *files = realloc(*files, sizeof(FileInfo) * (*file_count + 1));
            (*files)[*file_count] = new_file;
            (*file_count)++;
        }
    }
    closedir(dir);
}

