fn main() {
    let a = [[1, 2, 3], [4, 5, 6], [7, 8, 9]];
    let b = [[9, 8, 7], [6, 5, 4], [3, 2, 1]];

    // Compute C = A x B
    let mut c = [[0i64; 3]; 3];
    for i in 0..3 {
        for j in 0..3 {
            for k in 0..3 {
                c[i][j] += a[i][k] * b[k][j];
            }
        }
    }

    // Compute determinant of C
    // Using the formula for a 3x3 matrix:
    // det(M) = m[0][0]*(m[1][1]*m[2][2] - m[1][2]*m[2][1]) -
    //          m[0][1]*(m[1][0]*m[2][2] - m[1][2]*m[2][0]) +
    //          m[0][2]*(m[1][0]*m[2][1] - m[1][1]*m[2][0])
    let det_c = c[0][0] * (c[1][1] * c[2][2] - c[1][2] * c[2][1])
              - c[0][1] * (c[1][0] * c[2][2] - c[1][2] * c[2][0])
              + c[0][2] * (c[1][0] * c[2][1] - c[1][1] * c[2][0]);

    // Output formatting
    println!("=== Matrix Operations ===");
    println!();

    println!("Matrix A:");
    for row in &a {
        println!("  {:4d} {:4d} {:4d}", row[0], row[1], row[2]);
    }
    println!();

    println!("Matrix B:");
    for row in &b {
        println!("  {:4d} {:4d} {:4d}", row[0], row[1], row[2]);
    }
    println!();

    println!("A x B =");
    for row in &c {
        println!("  {:4d} {:4d} {:4d}", row[0], row[1], row[2]);
    }
    println!();

    println!("Determinant: {}", det_c);
}
